// AXE modifications: one selector and shared fixed/custom field output.

use clap::Parser;
use procfs::{
    prelude::*,
    process::{self, Process},
};
use procutils_common::{MAX_TERM_WIDTH, man::ManContent};
use std::{collections::HashMap, process::ExitCode};

mod fields;
mod format;
mod format_helpers;
mod output;
mod selection;

pub use selection::preprocess_argv;

use fields::ProcessContext;
use format::{FieldSpec, parse_format_spec};
use selection::{BsdOptions, Selection};

pub const MAN: ManContent = ManContent {
    description: Some(include_str!("../man/description.man")),
    extra_sections: &[
        (
            "FIELD DESCRIPTIONS",
            include_str!("../man/field_descriptions.man"),
        ),
        ("EXAMPLES", include_str!("../man/examples.man")),
        ("NOTES", include_str!("../man/notes.man")),
        ("SEE ALSO", include_str!("../man/see_also.man")),
    ],
};

/// Report a snapshot of the current processes.
#[derive(Parser)]
#[command(name = "ps", version, about, max_term_width = MAX_TERM_WIDTH)]
pub struct Args {
    /// Select all processes (same as -e).
    #[arg(short = 'A', long)]
    all: bool,

    /// Select all processes (same as -A).
    #[arg(short)]
    e: bool,

    /// Full-format listing.
    #[arg(short)]
    f: bool,

    /// Select processes with a terminal, except session leaders.
    #[arg(short)]
    a: bool,

    /// Select your processes, including those without a terminal.
    #[arg(short)]
    x: bool,

    /// Select active processes only.
    #[arg(short)]
    r: bool,

    /// Wide output. Use twice for unlimited width.
    #[arg(short, action = clap::ArgAction::Count)]
    w: u8,

    /// Set the output width in columns.
    #[arg(
        long = "cols",
        visible_aliases = ["columns", "width"],
        value_name = "WIDTH",
        allow_hyphen_values = true
    )]
    width: Vec<String>,

    /// Select by PID. Accepts comma- or space-separated lists.
    #[arg(short, long = "pid", value_name = "PID", allow_hyphen_values = true)]
    p: Vec<String>,

    /// Select by effective user name or ID.
    #[arg(
        short = 'u',
        long = "user",
        value_name = "USER",
        allow_hyphen_values = true
    )]
    user_filter: Vec<String>,

    /// Select by real user name or ID.
    #[arg(
        short = 'U',
        long = "ruser",
        value_name = "USER",
        allow_hyphen_values = true
    )]
    real_user_filter: Vec<String>,

    /// Custom output format. Comma- or space-separated list of column
    /// names; multiple `-o` arguments are concatenated. Use
    /// `name=label` to override a column's header. See FIELD
    /// DESCRIPTIONS for the supported names.
    #[arg(short = 'o', long = "format", allow_hyphen_values = true)]
    format: Vec<String>,

    // Generated by preprocess_argv so BSD defaults never leak into Unix flags.
    #[arg(long, hide = true, value_parser = selection::parse_bsd_options)]
    bsd_options: Vec<BsdOptions>,
}

/// Caller-context shared across fixed and custom output.
struct RunContext {
    selection: Selection,
    boot_time: u64,
    total_mem: u64,
    uptime_secs: f64,
    tps: u64,
    output_width: Option<usize>,
}

fn build_ctx(args: &Args) -> Result<RunContext, String> {
    let myself = Process::myself().map_err(|e| format!("ps: {e}"))?;
    let status = myself.status().map_err(|e| format!("ps: {e}"))?;
    let stat = myself.stat().map_err(|e| format!("ps: {e}"))?;
    let selection = Selection::new(args, status.euid, stat.tty_nr)?;

    let boot_time = procfs::KernelStats::current().map(|k| k.btime).unwrap_or(0);
    let total_mem = procfs::Meminfo::current().map(|m| m.mem_total).unwrap_or(1);
    let mut boot_clock = libc::timespec {
        tv_sec: 0,
        tv_nsec: 0,
    };
    // SAFETY: CLOCK_BOOTTIME writes an initialized, correctly aligned timespec.
    if unsafe { libc::clock_gettime(libc::CLOCK_BOOTTIME, &mut boot_clock) } != 0 {
        return Err(format!("ps: {}", std::io::Error::last_os_error()));
    }
    let uptime_secs = boot_clock.tv_sec as f64 + boot_clock.tv_nsec as f64 * 1.0e-9;

    Ok(RunContext {
        selection,
        boot_time,
        total_mem,
        uptime_secs,
        tps: procfs::ticks_per_second(),
        output_width: output::width(args).map_err(|error| format!("ps: {error}"))?,
    })
}

pub fn run(args: Args) -> ExitCode {
    let ctx = match build_ctx(&args) {
        Ok(ctx) => ctx,
        Err(error) => {
            eprintln!("{error}");
            return ExitCode::FAILURE;
        }
    };

    if !args.format.is_empty() {
        let specs = match parse_format_spec(&args.format) {
            Ok(s) if s.is_empty() => {
                eprintln!("ps: -o requires at least one column");
                return ExitCode::from(2);
            }
            Ok(s) => s,
            Err(e) => {
                eprintln!("{e}");
                return ExitCode::from(2);
            }
        };
        return run_with_format(&ctx, &specs);
    }

    run_with_format(&ctx, &fixed_format(&ctx.selection, args.f))
}

fn fixed_format(selection: &Selection, full: bool) -> Vec<FieldSpec> {
    let columns: &[(&str, &str)] = if full {
        &[
            ("user", "UID"),
            ("pid", "PID"),
            ("ppid", "PPID"),
            ("c", "C"),
            ("start", "STIME"),
            ("tty", "TTY"),
            ("time", "TIME"),
            ("args", "CMD"),
        ]
    } else if selection.user_format {
        &[
            ("user", "USER"),
            ("pid", "PID"),
            ("%cpu", "%CPU"),
            ("%mem", "%MEM"),
            ("vsz", "VSZ"),
            ("rss", "RSS"),
            ("tty", "TTY"),
            ("stat", "STAT"),
            ("start", "START"),
            ("bsdtime", "TIME"),
            ("args", "COMMAND"),
        ]
    } else if selection.bsd {
        &[
            ("pid", "PID"),
            ("tty", "TTY"),
            ("stat", "STAT"),
            ("bsdtime", "TIME"),
            ("args", "COMMAND"),
        ]
    } else {
        &[
            ("pid", "PID"),
            ("tty", "TTY"),
            ("time", "TIME"),
            ("comm", "CMD"),
        ]
    };
    columns
        .iter()
        .map(|&(name, header)| FieldSpec {
            field: fields::lookup(name).expect("fixed ps field"),
            label: Some(header.to_string()),
        })
        .collect()
}

fn run_with_format(ctx: &RunContext, specs: &[FieldSpec]) -> ExitCode {
    let all_procs = match process::all_processes() {
        Ok(iter) => iter,
        Err(e) => {
            eprintln!("ps: {e}");
            return ExitCode::FAILURE;
        }
    };

    let mut uid_cache = procutils_common::uid::UidCache::new();
    let mut gid_cache: HashMap<u32, String> = HashMap::new();

    let needs_cmdline = specs.iter().any(|spec| spec.field.name == "args");

    let mut rows: Vec<(i32, Vec<String>)> = Vec::new();
    for proc_result in all_procs {
        let proc = match proc_result {
            Ok(p) => p,
            Err(_) => continue,
        };
        let stat = match proc.stat() {
            Ok(s) => s,
            Err(_) => continue,
        };
        let status = match proc.status() {
            Ok(s) => s,
            Err(_) => continue,
        };
        if !ctx.selection.includes(&stat, &status) {
            continue;
        }
        let cmdline = if needs_cmdline {
            proc.cmdline().unwrap_or_default().join(" ")
        } else {
            String::new()
        };

        let mut pctx = ProcessContext {
            stat: &stat,
            status: &status,
            cmdline: &cmdline,
            uid_cache: &mut uid_cache,
            gid_cache: &mut gid_cache,
            boot_time: ctx.boot_time,
            uptime_secs: ctx.uptime_secs,
            tps: ctx.tps,
            total_mem_kb: ctx.total_mem / 1024,
        };
        let cells: Vec<String> = specs.iter().map(|s| (s.field.compute)(&mut pctx)).collect();
        rows.push((stat.pid, cells));
    }

    rows.sort_by_key(|(pid, _)| *pid);

    let _ = output::write_table(
        specs,
        &rows,
        ctx.output_width,
        &mut std::io::stdout().lock(),
    );
    if rows.is_empty() {
        ExitCode::FAILURE
    } else {
        ExitCode::SUCCESS
    }
}

